/**
 * The UI's door to the core. Import IPC from here, never from `bindings.ts` directly: that file
 * is generated by tauri-specta (`pnpm bindings`) and must not be edited by hand.
 *
 * The four channels (CLAUDE.md, architecture rule 3):
 * - Commands (`invoke`): `commands.*`. One that can fail returns `{ status: "ok", data }` or
 *   `{ status: "error", error }`, and `error` is always a `JerryError`; anything else it rejects
 *   with (an unknown command, a bad argument) is a bug and is thrown. Show the error with
 *   `errorText` from `src/strings`.
 * - Streams (`Channel`): `stream(onMessage)`; binary messages start with `messageHeader`. Folder
 *   listings: `openListing`, re-sorted with its `sort`.
 * - Events (`emit` from Rust to all windows): `subscribe(events.*, handler)`. The page only
 *   listens; it never emits.
 * - Custom protocols: `protocolUrl("icon", key)` for an `<img src>`.
 */

export type {
  Accent,
  Appearance,
  ClickToOpen,
  Density,
  DragAction,
  ErrorCode,
  JerryError,
  ListingTarget,
  Settings,
  Sort,
  SortColumn,
  Startup,
  Theme,
  View,
  WindowsAccent,
} from "./bindings";
export { commands, events } from "./bindings";
export { HEADER_BYTES, messageHeader, stream } from "./channel";
export { type CoreEvent, subscribe } from "./events";
export {
  decodeListingMessage,
  type ListingBatch,
  type ListingDone,
  type ListingFailed,
  ListingKind,
  type ListingMessage,
  type ListingOrder,
  type OpenListing,
  openListing,
} from "./listing";
export { type Protocol, protocolUrl } from "./protocol";
